from parcel import config
import parcel.quote


def format_money(amount):
    return f"{config.SETTINGS['currency']} {amount:,.2f}"


def service_name(carrier):
    if carrier == "postnl":
        return "PostNL Standard"
    elif carrier == "dhl":
